# ── Constants ───────────────────────────────────────────────────

class TestConstants:
    def test_all_digits_present(self):
        for d in range(10):
            assert d in DIGIT_TO_CONSONANTS, f"Missing digit {d}"

    def test_digit_to_consonants_non_empty(self):
        for d in range(10):
            assert len(DIGIT_TO_CONSONANTS[d]) > 0, f"Digit {d} has no consonants"

    def test_digraphs_list(self):
        assert DIGRAPHS == ["sh", "ch", "th", "ck"]

    def test_silent_letters(self):
        assert SILENT_LETTERS == frozenset("ewy")

# ── digit_to_consonants ────────────────────────────────────────

class TestDigitToConsonants:
    @pytest.mark.parametrize(
        "digit,expected",
        [
            (0, ["s", "z"]),
            (1, ["t", "d"]),
            (2, ["n"]),
            (3, ["m"]),
            (4, ["r"]),
            (5, ["l"]),
            (6, ["sh", "ch", "j", "g"]),
            (7, ["k", "c", "q", "ck"]),
            (8, ["f", "v"]),
            (9, ["p", "b"]),
        ],
    )
    def test_all_digits(self, digit, expected):
        assert digit_to_consonants(digit) == expected

    def test_invalid_digit_negative(self):
        with pytest.raises(ValueError):
            digit_to_consonants(-1)

    def test_invalid_digit_too_large(self):
        with pytest.raises(ValueError):
            digit_to_consonants(10)

    def test_invalid_type_string(self):
        with pytest.raises(ValueError):
            digit_to_consonants("3")

# ── consonant_to_digit ─────────────────────────────────────────

class TestConsonantToDigit:
    @pytest.mark.parametrize(
        "consonant,expected",
        [
            ("s", 0), ("z", 0),
            ("t", 1), ("d", 1),
            ("n", 2),
            ("m", 3),
            ("r", 4),
            ("l", 5),
            ("sh", 6), ("ch", 6), ("th", 6), ("j", 6), ("g", 6),
            ("k", 7), ("c", 7), ("q", 7), ("ck", 7),
            ("f", 8), ("v", 8),
            ("p", 9), ("b", 9),
        ],
    )
    def test_all_consonants(self, consonant, expected):
        assert consonant_to_digit(consonant) == expected

    def test_unknown_consonant(self):
        with pytest.raises(KeyError):
            consonant_to_digit("x")

# ── decode_word ────────────────────────────────────────────────

class TestDecodeWord:
    def test_digraph_sh(self):
        assert decode_word("shack") == [6, 7]

    def test_digraph_ch(self):
        assert decode_word("chick") == [6, 7]

    def test_digraph_th(self):
        assert decode_word("thick") == [6, 7]

    def test_digraph_ck(self):
        assert decode_word("back") == [9, 7]

    def test_single_consonants(self):
        assert decode_word("stop") == [0, 1, 9]

    def test_vowels_skipped(self):
        assert decode_word("sato") == [0, 1]  # s-a-t-o → 0-1

    def test_silent_letters_skipped(self):
        assert decode_word("sway") == [0]  # s-w-a-y → 0 (w,y silent)

    def test_empty_string(self):
        assert decode_word("") == []

    def test_case_insensitive(self):
        assert decode_word("SHACK") == [6, 7]

    def test_mixed_case(self):
        assert decode_word("ShAcK") == [6, 7]

    def test_invalid_type(self):
        with pytest.raises(TypeError):
