class TestEncodeDigits:
    def test_single_digit(self):
        result = encode_digits([0])
        assert set(result) == {"s", "z"}

    def test_two_digits(self):
        result = encode_digits([0, 1])
        assert sorted(result) == ["sd", "st", "zd", "zt"]

    def test_empty_list(self):
        assert encode_digits([]) == [""]

    def test_all_same_digit(self):
        result = encode_digits([2, 2])
        assert result == ["nn"]

    def test_invalid_type(self):
        with pytest.raises(TypeError):
