class TestNumberDigits:
    def test_positive_integer(self):
        assert number_to_digits(67) == [6, 7]

    def test_single_digit(self):
        assert number_to_digits(5) == [5]

    def test_zero(self):
        assert number_to_digits(0) == [0]

    def test_negative_integer(self):
        assert number_to_digits(-123) == [1, 2, 3]

    def test_large_number(self):
        assert number_to_digits(1234567890) == [1, 2, 3, 4, 5, 6, 7, 8, 9, 0]

    def test_invalid_type_string(self):
        with pytest.raises(TypeError):
            number_to_digits("123")

    def test_round_trip_number(self):
        n = 67890
        digits = number_to_digits(n)
        assert digits_to_number(digits) == n

    def test_round_trip_zero(self):
        assert digits_to_number(number_to_digits(0)) == 0

    def test_round_trip_large(self):
        n = 1234567890
        assert digits_to_number(number_to_digits(n)) == n

# ── Round-trip: decode(encode) ────────────────────────────────

class TestRoundTrip:
    def test_round_trip_small(self):
        """decode_word of an encoded consonant sequence should recover digits."""
        for d in range(10):
            consonants = digit_to_consonants(d)
            for c in consonants:
                decoded = decode_word(c)
                assert decoded == [d], f"Failed for digit {d}, consonant '{c}'"

    def test_round_trip_two_digits(self):
        """Round-trip through encode then decode for two-digit numbers."""
        digits = [1, 2]
        encoded_list = encode_digits(digits)
        for enc in encoded_list:
            decoded = decode_word(enc)
            assert decoded == digits, f"Failed round-trip for {enc}"

    def test_round_trip_three_digits(self):
        """Round-trip through encode then decode for three-digit numbers."""
        digits = [3, 4, 5]
        encoded_list = encode_digits(digits)
        for enc in encoded_list:
            decoded = decode_word(enc)
            assert decoded == digits, f"Failed round-trip for {enc}"

    def test_round_trip_all_numbers_0_to_99(self):
        """Every number 0..99 should round-trip through encode→decode."""
        for n in range(100):
            digits = number_to_digits(n)
            encoded_list = encode_digits(digits)
            assert len(encoded_list) > 0, f"No encodings for {n}"
            for enc in encoded_list:
                decoded = decode_word(enc)
                assert decoded == digits, (
                    f"Round-trip failed: n={n}, digits={digits}, "
                    f"encoded='{enc}', decoded={decoded}"
                )
"}

