class TestEncodeDigits:
    def test_single_digit_0(self):
        assert set(encode_digits([0])) == {"s", "z"}

    def test_single_digit_1(self):
        assert set(encode_digits([1])) == {"t", "d"}

    def test_two_digits_combinations(self):
        result = encode_digits([0, 1])
        # s/t × t/d → st, sd, zt, zd
        expected = ["st", "sd", "zt", "zd"]
        assert sorted(result) == sorted(expected)

    def test_three_digits(self):
        result = encode_digits([0, 1, 2])
        # s/z × t/d × n → stn, sdn, ztn, zdn
        expected = ["stn", "sdn", "ztn", "zdn"]
        assert sorted(result) == sorted(expected)

    def test_digit_with_digraph_options(self):
        result = encode_digits([6])
        # 6 → sh, ch, j, g
        expected = ["sh", "ch", "j", "g"]
        assert set(result) == set(expected)

    def test_empty_digits(self):
        assert encode_digits([]) == [""]

    def test_all_nine_digits(self):
        result = encode_digits([0, 1, 2, 3, 4, 5, 6, 7, 8])
        # Each digit has at least one consonant, so product is non-empty
        assert len(result) > 0
        for enc in result:
            assert len(enc) >= 9  # each digit contributes ≥1 char

    def test_invalid_type(self):
        with pytest.raises(TypeError):
            encode_digits("123")

    def test_invalid_type_int(self):
        with pytest.raises(TypeError):
            encode_digits(42)

    def test_tuple_input_accepted(self):
        result = encode_digits((0, 1))
