class TestChunkDigits:
    def test_basic(self):
        assert chunk_digits([1, 2, 3, 4, 5], k=2) == [[1, 2], [3, 4], [5]]

    def test_exact_multiple(self):
        assert chunk_digits([1, 2, 3, 4], k=2) == [[1, 2], [3, 4]]

    def test_single_chunk(self):
        assert chunk_digits([1, 2, 3], k=5) == [[1, 2, 3]]

    def test_empty_list(self):
        assert chunk_digits([], k=3) == []

    def test_default_k_is_3(self):
        result = chunk_digits([1, 2, 3, 4, 5])
        assert result == [[1, 2, 3], [4, 5]]

    def test_tuple_input_accepted(self):
        assert chunk_digits((1, 2, 3), k=2) == [[1, 2], [3]]

    def test_invalid_type_string(self):
        with pytest.raises(TypeError):
            chunk_digits("123", k=2)

    def test_invalid_type_int(self):
        with pytest.raises(TypeError):
            chunk_digits(12345, k=2)


class TestChunkNumber:
    def test_basic(self):
        assert chunk_number(1234567890, k=3) == [123, 456, 789, 0]

    def test_small_number(self):
        assert chunk_number(67, k=2) == [67]

    def test_single_digit(self):
        assert chunk_number(5, k=3) == [5]

    def test_zero(self):
        assert chunk_number(0, k=3) == [0]

    def test_negative_number(self):
        # abs(-1234567890) = 1234567890
        result = chunk_number(-1234567890, k=3)
        assert result == [123, 456, 789, 0]

    def test_default_k_is_3(self):
        result = chunk_number(1234567890)
        assert result == [123, 456, 789, 0]

    def test_invalid_type_string(self):
        with pytest.raises(TypeError):
            chunk_number("123", k=3)


class TestMnemonicForChunk:
    def test_basic(self):
        result = mnemonic_for_chunk([0, 1])
        assert sorted(result) == ["sd", "st", "zd", "zt"]

    def test_single_digit(self):
        result = mnemonic_for_chunk([2])
        assert result == ["n"]

    def test_empty_chunk(self):
        result = mnemonic_for_chunk([])
        assert result == [""]

    def test_three_digits(self):
        result = mnemonic_for_chunk([3, 4, 5])
        # m × r × l → mrl
        assert result == ["mrl"]


class TestChunkWithMnemonics:
    def test_basic(self):
        result = chunk_with_mnemonics(67, k=2)
        assert len(result) == 1
        entry = result[0]
        assert entry["chunk"] == 67
        assert entry["digits"] == [6, 7]
        # mnemonics for [6,7]: sh/ch/j/g × k/c/q/ck → many combos
        assert len(entry["mnemonics"]) > 0

    def test_multiple_chunks(self):
        result = chunk_with_mnemonics(123456, k=3)
        assert len(result) == 2
        assert result[0]["chunk"] == 123
        assert result[0]["digits"] == [1, 2, 3]
        assert result[1]["chunk"] == 456
        assert result[1]["digits"] == [4, 5, 6]

    def test_single_digit(self):
        result = chunk_with_mnemonics(5, k=3)
        assert len(result) == 1
        assert result[0]["chunk"] == 5
        assert result[0]["digits"] == [5]

    def test_zero(self):
        result = chunk_with_mnemonics(0, k=3)
        assert len(result) == 1
        assert result[0]["chunk"] == 0
        assert result[0]["digits"] == [0]

    def test_default_k_is_3(self):
        result = chunk_with_mnemonics(1234567890)
        assert len(result) == 4
        assert result[0]["chunk"] == 123
        assert result[-1]["chunk"] == 0

    def test_negative_number(self):
        result = chunk_with_mnemonics(-67, k=2)
        assert len(result) == 1
        assert result[0]["chunk"] == 67


class TestChunkRoundTrip:
    """Verify that chunking and reassembling recovers the original number."""

    def test_round_trip_small(self):
        n = 67890
        chunks = chunk_number(n, k=3)
        # Reassemble: pad each chunk to k digits except last
        digits = []
        for i, c in enumerate(chunks):
            if i < len(chunks) - 1:
                s = str(c).zfill(3)
            else:
                s = str(c)
            digits.extend([int(d) for d in s])
        from major_system.mapping import digits_to_number
        recovered = digits_to_number(digits)
        assert recovered == n, f"Failed: n={n}, chunks={chunks}, recovered={recovered}"

    def test_round_trip_various(self):
        from major_system.mapping import number_to_digits, digits_to_number

        for n in [0, 1, 42, 67, 99, 123, 500, 1234, 98765]:
            chunks = chunk_number(n, k=3)
            # Reassemble from digits
            all_digits = []
            for c in chunks:
                all_digits.extend(number_to_digits(c))
            recovered = digits_to_number(all_digits)
            assert recovered == n, f"Failed: n={n}, chunks={chunks}, recovered={recovered}"
